# Generate one-hot vectors
row_one_hot = {}
col_one_hot = {}

for z, (row, col) in period_group.items():
    row_vec = [0 for _ in range(7)]
    col_vec = [0 for _ in range(18)]
    row_vec[row-1] = 1.0
    col_vec[col-1] = 1.0
    row_one_hot[z] = row_vec
    col_one_hot[z] = col_vec
    
# define min and max values for each atomic and graph descriptor
scales = {'atomic_mass': (min(atomic_mass.values()), max(atomic_mass.values())),
          'atomic_number': (min(atomic_number.values()), max(atomic_number.values())),
          'period': (min(period.values()), max(period.values())),
          'valence_sp': (min(valence_sp.values()), max(valence_sp.values())),
          'valence_d': (min(valence_d.values()), max(valence_d.values())),
          'valence_f': (min(valence_f.values()), max(valence_f.values())),
          'covalent_radius': (min(covalent_radius.values()), max(covalent_radius.values())),
          'vdw_radius': (min(vdw_radius.values()), max(vdw_radius.values())),
          'coordination_number': (0, 12), # define conservative upper bound of 12 as atoms with more than 12 bonds are exceedingly rare even in organometallics
          'electronegativity': (min(electronegativity.values()), max(electronegativity.values())),
          'polarizability': (min(polarizability.values()), max(polarizability.values())),
          'ionization_potential': (min(ionization_potential.values()), max(ionization_potential.values())),
          'charge': (-3, 3), # define heuristic range of +/-3 for common molecular charges
          'spinmult': (1, 6)} # define heuristic range of 1-6 (i.e., singlet to sextet)

# Note: when data was unavailable, values from other sources or from the element with the closest atomic number were used
# electronegativity: He, Ne, Ar, Kr, Xe, Rn treated as 0. Po and At values from http://www.webelements.com.
# vdw_radius: Po, At, Rn, Fr, and Ra values from http://www.webelements.com. Fm value from Es.


def atomic_fingerprint(atomic_number_, num_bonds=None):
    '''
    Fingerprint nodes with atomic properties.
    INPUTS:
        atomic_symbol: str
            Atomic symbol specifying element.
        num_bonds: int
            Number of bonds to other atoms in the molecule.
    OUTPUTS:
        node_features: dict
            Dictionary of atomic features.
    '''
    atomic_symbol = atomic_number_to_symbol[int(atomic_number_)]
    node_features = {'atomic_mass': atomic_mass[atomic_symbol],
                     'atomic_number': atomic_number[atomic_symbol],
                     'period': period[atomic_symbol],
                     'valence_sp': valence_sp[atomic_symbol],
                     'valence_d': valence_d[atomic_symbol],
                     'valence_f': valence_f[atomic_symbol],
                     'covalent_radius': covalent_radius[atomic_symbol],
                     'vdw_radius': vdw_radius[atomic_symbol],
                     'electronegativity': electronegativity[atomic_symbol],
                     'polarizability': polarizability[atomic_symbol],
                     'ionization_potential': ionization_potential[atomic_symbol]}
    scale_dict = scales
    
    if num_bonds is not None:
        node_features['coordination_number'] = num_bonds

    # scale node features
    for key, value in zip(node_features.keys(), node_features.values()):
        min_val, max_val = scale_dict[key]
        node_features[key] = (value - min_val) / (max_val - min_val)
    
    return list(node_features.values())